            sources.append((color, [[1 if v else 0 for v in row] for row in pat]))

    for color,r0,r1,c0,c1,pat in frames:
        if any(v not in (0,color) for row in pat for v in row):
            continue
        ih, iw = r1-r0-1, c1-c0-1
        candidates = [(s,p) for s,p in sources if s != color]
        if not candidates:
            continue
        s,p = min(candidates, key=lambda x: abs(len(x[1])-ih)+abs(len(x[1][0])-iw))
